from enum import Enum

class Direction(Enum):
    UP = 1
    DOWN = -1
    IDLE = 0

class Request:
    def __init__(self, floor, direction=None):
        self.floor = floor
        self.direction = direction  # None for car requests

class Elevator:
    def __init__(self, id, current_floor=0):
        self.id = id
        self.current_floor = current_floor
        self.direction = Direction.IDLE
        self.requests = []  # List of floors to visit
        self.door_open = False
        self.in_service = True
    def add_request(self, floor):
        if floor not in self.requests:
            self.requests.append(floor)
    def step(self):
        if not self.requests:
            self.direction = Direction.IDLE
            return
        # Move towards next request
        target = self.requests[0]
        if self.current_floor < target:
            self.current_floor += 1
            self.direction = Direction.UP
        elif self.current_floor > target:
            self.current_floor -= 1
            self.direction = Direction.DOWN
        else:
            self.door_open = True
            self.requests.pop(0)
            self.door_open = False

class Scheduler:
    def assign(self, elevators, request):
        # Simple: pick closest idle or least loaded elevator
        candidates = [e for e in elevators if e.in_service]
        best = min(candidates, key=lambda e: abs(e.current_floor - request.floor))
        best.add_request(request.floor)

class ElevatorSystem:
    def __init__(self, num_elevators):
        self.elevators = [Elevator(i) for i in range(num_elevators)]
        self.scheduler = Scheduler()
    def pickup(self, floor, direction):
        req = Request(floor, direction)
        self.scheduler.assign(self.elevators, req)
    def step(self):
        for e in self.elevators:
            e.step()

