class PaymentProcessor:
    def __init__(self):
        self.balance = 0
    def insert_money(self, amount):
        self.balance += amount
    def refund(self):
        change = self.balance
        self.balance = 0
        return change
    def pay(self, price):
        if self.balance >= price:
            change = self.balance - price
            self.balance = 0
            return True, change
        return False, 0

class Display:
    def show(self, message):
        print(message)

class VendingMachine:
    def __init__(self):
        self.inventory = Inventory()
        self.payment = PaymentProcessor()
        self.display = Display()
    def select_product(self, name):
        product = self.inventory.get_product(name)
        if not product or product.quantity == 0:
            self.display.show('Out of stock')
            return
        self.display.show(f'Price: {product.price}')
        return product
    def insert_money(self, amount):
        self.payment.insert_money(amount)
    def buy(self, name):
        product = self.inventory.get_product(name)
        if not product or product.quantity == 0:
            self.display.show('Out of stock')
            return
        success, change = self.payment.pay(product.price)
        if success:
            self.inventory.reduce_stock(name)
            self.display.show(f'Dispensing {name}, change: {change}')
        else:
            self.display.show('Insufficient funds')

