        self.members[member.member_id] = member

    def remove_member(self, member_id):
        if member_id in self.members:
            del self.members[member_id]

    def borrow_book(self, member_id, isbn):
        if (member_id in self.members and isbn in self.books and
                not self.books[isbn].is_borrowed):
            self.books[isbn].is_borrowed = True
            self.members[member_id].borrowed_books.append(isbn)

    def return_book(self, member_id, isbn):
        if (member_id in self.members and isbn in self.books and
                isbn in self.members[member_id].borrowed_books):
            self.books[isbn].is_borrowed = False
            self.members[member_id].borrowed_books.remove(isbn)

