class Logger:
    def __init__(self, name):
        self.name = name
        self.handlers = []
        self.level = 'INFO'
        self.lock = threading.Lock()
    def add_handler(self, handler):
        self.handlers.append(handler)
    def log(self, level, msg):
        if self._should_log(level):
            record = LogRecord(level, msg)
            with self.lock:
                for handler in self.handlers:
                    handler.emit(record)
    def info(self, msg):
        self.log('INFO', msg)
    def debug(self, msg):
        self.log('DEBUG', msg)
    def _should_log(self, level):
        levels = ['DEBUG', 'INFO', 'WARNING', 'ERROR']
        return levels.index(level) >= levels.index(self.level)

class CacheEntry:
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.prev = self.next = None

class LRUEvictionPolicy:
    def __init__(self):
        self.head = CacheEntry(None, None)
        self.tail = CacheEntry(None, None)
        self.head.next = self.tail
        self.tail.prev = self.head

    def move_to_front(self, entry):
        self._remove(entry)
        self._add_to_front(entry)

    def _add_to_front(self, entry):
        entry.next = self.head.next
        entry.prev = self.head
        self.head.next.prev = entry
        self.head.next = entry

    def _remove(self, entry):
        entry.prev.next = entry.next
        entry.next.prev = entry.prev

    def evict(self):
        lru = self.tail.prev
        if lru == self.head:
            return None
        self._remove(lru)
        return lru.key

class Cache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.data = {}
        self.policy = LRUEvictionPolicy()

    def get(self, key):
        if key in self.data:
            entry = self.data[key]
            self.policy.move_to_front(entry)
            return entry.value
        return None

    def set(self, key, value):
        if key in self.data:
            entry = self.data[key]
            entry.value = value
            self.policy.move_to_front(entry)
        else:
            if len(self.data) >= self.capacity:
                evict_key = self.policy.evict()
                if evict_key:
                    del self.data[evict_key]
            entry = CacheEntry(key, value)
            self.data[key] = entry
            self.policy._add_to_front(entry)

