from abc import ABC, abstractmethod

class BackoffStrategy(ABC):
    @abstractmethod
    def next_delay(self, attempt):
        pass

class FixedBackoff(BackoffStrategy):
    def __init__(self, delay):
        self.delay = delay
    def next_delay(self, attempt):
        return self.delay

class ExponentialBackoff(BackoffStrategy):
    def __init__(self, initial, factor, max_delay):
        self.initial = initial
        self.factor = factor
        self.max_delay = max_delay
    def next_delay(self, attempt):
        return min(self.initial * (self.factor ** (attempt - 1)), self.max_delay)

class Retry:
    def __init__(self, max_attempts, backoff_strategy, retry_exceptions):
        self.max_attempts = max_attempts
        self.backoff_strategy = backoff_strategy
        self.retry_exceptions = retry_exceptions
        self._lock = threading.Lock()
    def call(self, func, *args, **kwargs):
        attempt = 1
        while attempt <= self.max_attempts:
            try:
                return func(*args, **kwargs)
            except self.retry_exceptions:
                if attempt == self.max_attempts:
                    raise
                delay = self.backoff_strategy.next_delay(attempt)
                time.sleep(delay)
                attempt += 1

def retry(max_attempts=3, backoff_strategy=None, retry_exceptions=(Exception,)):
    def decorator(func):
        r = Retry(max_attempts, backoff_strategy, retry_exceptions)
        def wrapper(*args, **kwargs):
            return r.call(func, *args, **kwargs)
        return wrapper
    return decorator

